sys_script_fix.script:
(function () {
    // Creates a Not found mapping for every active Konversational America user
    // without a Xero mapping yet. The daily job then matches them in one call to Xero.
    var COMPANY_NAME = 'Konversational America';

    var company = new GlideRecord('core_company');
    if (!company.get('name', COMPANY_NAME)) {
        gs.error('[Xero initial load] Company not found: ' + COMPANY_NAME);
        return;
    }

    var created = 0, skipped = 0;
    var usr = new GlideRecord('sys_user');
    usr.addQuery('company', company.getUniqueValue());
    usr.addActiveQuery();
    usr.query();

    while (usr.next()) {
        var map = new GlideRecord('x_snc_spm_xero_i_0_external_user_mapping');
        map.addQuery('user', usr.getUniqueValue());
        map.addQuery('tool', 'xero');
        map.query();
        if (map.hasNext()) {
            // Already mapped (Matched or Not found): leave it as is
            skipped++;
            continue;
        }
        map.initialize();
        map.setValue('user', usr.getUniqueValue());
        map.setValue('tool', 'xero');
        map.setValue('email', usr.getValue('email'));
        map.setValue('status', 'not_found');
        map.setValue('message', 'Pending first check in Xero');
        map.insert();
        created++;
    }
    gs.info('[Xero initial load] Created: ' + created + ' | Already mapped: ' + skipped);
})();
